"""
add_single_point_potential_section.py
Inserts Section 2.1 Figure and detailed mathematical explanation into PFDC_Manuscript.tex.
"""

import sys

with open("PFDC_Manuscript.tex", "r", encoding="utf-8") as f:
    content = f.read()

target = r"""where $R^{\mathrm{core}}$ represents the core radius of absolute certainty, $R^{\mathrm{decay}}$ is the decay shell width, $\lambda > 0$ governs fall-off steepness, and $\alpha > 0$ controls decay curvature.

As illustrated in Figure~\ref{fig:stacking_2d}"""

replacement = r"""where $R^{\mathrm{core}}$ represents the core radius of absolute certainty, $R^{\mathrm{decay}}$ is the decay shell width, $\lambda > 0$ governs fall-off steepness, and $\alpha > 0$ controls decay curvature.

\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{figures/single_point_potential_2d_3d.png}
\caption{Electrostatic potential field, core and decay radii, and directional force vector dynamics of an isolated support anchor $\mathbf{x}_i$ ($+q_i$). (a) 2D concentric equipotential shells and radial vector force field $\mathbf{F}(\mathbf{x})$: the inner deterministic core boundary ($R^{\mathrm{core}}$) transitions into an exponential decay shell ($R^{\mathrm{decay}}$); vector force arrows are longest near the center indicating maximum field strength and repulsive intensity, progressively diminishing to smaller arrows with distance before vanishing at the search horizon ($R^{\mathrm{core}} + R^{\mathrm{decay}}$). Explicit dimension markers indicate the core radius $R^{\mathrm{core}}$ and decay radius span $R^{\mathrm{decay}}$. (b) 3D continuous potential energy mesa landscape illustrating the flat saturation certainty plateau at height $1.0$ within $d \le R^{\mathrm{core}}$, transitioning into the smooth exponential decay skirt falling toward the zero-potential vacuum ground plane ($z=0$). (c) 1D cross-sectional influence profile $I(d)$ and corresponding vector force magnitude $\|\mathbf{F}(d)\|_2$, highlighting the absolute certainty core, exponential decay regime, and zero-support vacuum.}
\label{fig:single_point_potential}
\end{figure*}

\subsubsection{Geometry of an Isolated Point Anchor: Certainty Core, Decay Shell, and Vector Force Dynamics}
To ground the foundational mechanics of PFDC before considering multi-anchor superposition, Figure~\ref{fig:single_point_potential} illustrates the complete 2D and 3D electrostatic geometry generated by an isolated individual support anchor $\mathbf{x}_i$ with positive unit charge ($q_i = +1.0$):
\begin{enumerate}
    \item \textbf{Deterministic Certainty Core Zone ($d_{\mathbf{w}} \le R^{\mathrm{core}}$)}: Within the spherical (or ellipsoidal under metric tensor $\mathbf{W}$) boundary of radius $R^{\mathrm{core}}$, the potential influence saturates identically at $I(d_{\mathbf{w}}) \equiv 1.0$. In the 3D potential energy landscape (Figure~\ref{fig:single_point_potential}b), this zone manifests as a pristine, flat circular plateau of height $1.0$. Points situated within this core possess absolute local certainty ($100\%$ classification confidence) and exhibit certified mathematical invariance against any adversarial $\ell_2$ perturbation bounded by $(R^{\mathrm{core}} - d_{\mathbf{w}})/\sqrt{\max_j w_j}$ (Theorem~\ref{thm:robustness}).
    \item \textbf{Exponential Decay Shell ($R^{\mathrm{core}} < d_{\mathbf{w}} \le R^{\mathrm{core}} + R^{\mathrm{decay}}$)}: Across the radial span of width $R^{\mathrm{decay}}$, the scalar potential smoothly transitions from saturated confidence ($1.0$) to the background ground plane ($0.0$) according to the exponential fall-off kernel $I(d_{\mathbf{w}}) = \exp(-\lambda u^\alpha)$, where $u = (d_{\mathbf{w}} - R^{\mathrm{core}})/R^{\mathrm{decay}} \in (0, 1]$. In 3D space, this forms a continuous, differentiable exponential bell skirt (Figure~\ref{fig:single_point_potential}b), providing a smooth margin transition that eliminates the sharp step discontinuities of nearest-neighbor classifiers while retaining bounded spatial extent.
    \item \textbf{Zero-Support Vacuum Horizon ($d_{\mathbf{w}} > R^{\mathrm{core}} + R^{\mathrm{decay}}$)}: Beyond the search horizon $R^{\mathrm{horizon}} = R^{\mathrm{core}} + R^{\mathrm{decay}}$, the potential influence drops identically to zero ($I \equiv 0.0$). Unlike Gaussian Radial Basis Functions (RBF) which exert non-zero influence across the entire infinite domain $\mathbb{R}^D$, PFDC's strict compact support guarantees that distant outliers cannot corrupt local decision boundaries, while enabling sub-linear $\mathcal{O}(\log N)$ inference indexing via spatial Ball-Trees.
    \item \textbf{Continuous Directional Force Vector Field}: Concurrently with the scalar energy landscape, every point in space experiences an electrostatic vector force $\mathbf{F}(\mathbf{x}) = -\nabla I(d_{\mathbf{w}})$. As depicted in the 2D vector field (Figure~\ref{fig:single_point_potential}a) and 1D profile (Figure~\ref{fig:single_point_potential}c), the force field exhibits a characteristic distance-dependent strength profile:
    \begin{itemize}
        \item \emph{Maximum Strength Near the Center}: Near the anchor and the inner core boundary, the vector force arrows are \textbf{longest}, exerting powerful outward repulsive pressure that robustly drives opposing points away from the certainty basin.
        \item \emph{Progressive Falloff with Distance}: As the Euclidean distance $d_{\mathbf{w}}$ increases through the decay shell, the field intensity steadily decays, represented by progressively \textbf{smaller vector arrows}.
        \item \emph{Graceful Extinction at Horizon}: At the outer search horizon ($d_{\mathbf{w}} = R^{\mathrm{core}} + R^{\mathrm{decay}}$), the vector arrows smoothly shrink to zero length, ensuring zero residual force in the unpopulated feature vacuum.
    \end{itemize}
\end{enumerate}

As illustrated in Figure~\ref{fig:stacking_2d}"""

if target in content:
    content = content.replace(target, replacement, 1)
    with open("PFDC_Manuscript.tex", "w", encoding="utf-8") as f:
        f.write(content)
    print("Successfully inserted single point potential figure and body text into PFDC_Manuscript.tex!")
else:
    print("Target string not found in PFDC_Manuscript.tex!")
    sys.exit(1)
